//! Bounded CFG-aware optimization for compiler-generated bytecode.
//!
//! The pass propagates scalar constants through local slots and operand-stack
//! values, simplifies branches whose condition is known, and removes blocks
//! made unreachable by those branches. Local slots with disjoint CFG liveness
//! share frame storage. Potentially failing operations are only folded when
//! the existing comptime evaluator proves that they succeed.

use crate::ast::{BinOp, Expr, UnOp};
use crate::backend::{CallableSignature, CompiledProgram, SourceMapEntry};
use crate::instruction::{Instruction, ValueType};
use crate::template::ArrayTemplate;
use crate::value::Value;
use std::collections::{BTreeMap, BTreeSet, HashMap, VecDeque};

const MAX_REGION_INSTRUCTIONS: usize = 200_000;
const MAX_ANALYSIS_VISITS: usize = 1_000_000;
const MAX_TRACKED_VALUES: usize = 256;
const MAX_SLOT_COMPACTION_SLOTS: usize = 4_096;
const MAX_SLOT_FLOW_WORDS: usize = 250_000;
const MAX_SLOT_FLOW_OPERATIONS: usize = 4_000_000;
const MAX_SLOT_INTERFERENCE_OPERATIONS: usize = 2_000_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Scalar {
    Int(i64),
    UInt(u64),
    Float(u64),
    Bool(bool),
    Char(char),
    Nil,
}

impl Scalar {
    fn from_value(value: &Value) -> Option<Self> {
        Some(match value {
            Value::Int(value) => Self::Int(*value),
            Value::UInt(value) => Self::UInt(*value),
            Value::Float(value) => Self::Float(value.to_bits()),
            Value::Bool(value) => Self::Bool(*value),
            Value::Char(value) => Self::Char(*value),
            Value::Nil => Self::Nil,
            _ => return None,
        })
    }

    fn value(self) -> Value {
        match self {
            Self::Int(value) => Value::Int(value),
            Self::UInt(value) => Value::UInt(value),
            Self::Float(value) => Value::Float(f64::from_bits(value)),
            Self::Bool(value) => Value::Bool(value),
            Self::Char(value) => Value::Char(value),
            Self::Nil => Value::Nil,
        }
    }

    fn expression(self) -> Expr {
        match self {
            Self::Int(value) => Expr::Int(value),
            Self::UInt(value) => Expr::UInt(value),
            Self::Float(value) => Expr::Float(f64::from_bits(value)),
            Self::Bool(value) => Expr::Bool(value),
            Self::Char(value) => Expr::Char(value),
            Self::Nil => Expr::Nil,
        }
    }

    fn is_type(self, ty: &ValueType) -> bool {
        matches!(
            (self, ty),
            (Self::Int(_), ValueType::Int)
                | (Self::UInt(_), ValueType::UInt)
                | (Self::Float(_), ValueType::Float)
                | (Self::Bool(_), ValueType::Bool)
                | (Self::Char(_), ValueType::Char)
                | (Self::Nil, ValueType::Nil)
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct State {
    stack_height: usize,
    stack_values: HashMap<usize, Scalar>,
    locals: HashMap<usize, Scalar>,
}

impl State {
    fn new(stack_height: usize) -> Self {
        Self {
            stack_height,
            stack_values: HashMap::new(),
            locals: HashMap::new(),
        }
    }

    fn push(&mut self, value: Option<Scalar>) -> Result<(), ()> {
        let slot = self.stack_height;
        self.stack_height = self.stack_height.checked_add(1).ok_or(())?;
        if let Some(value) = value {
            self.stack_values.insert(slot, value);
            if self.stack_values.len() > MAX_TRACKED_VALUES {
                self.stack_values.clear();
            }
        }
        Ok(())
    }

    fn pop(&mut self) -> Result<Option<Scalar>, ()> {
        let slot = self.stack_height.checked_sub(1).ok_or(())?;
        self.stack_height = slot;
        Ok(self.stack_values.remove(&slot))
    }

    fn peek(&self) -> Option<Scalar> {
        self.stack_height
            .checked_sub(1)
            .and_then(|slot| self.stack_values.get(&slot).copied())
    }

    fn store_local(&mut self, slot: usize, value: Option<Scalar>) {
        let Some(value) = value else {
            self.locals.remove(&slot);
            return;
        };
        if !self.locals.contains_key(&slot) && self.locals.len() >= MAX_TRACKED_VALUES {
            self.locals.clear();
        }
        self.locals.insert(slot, value);
    }

    fn merge(&mut self, other: &Self) -> Result<bool, ()> {
        if self.stack_height != other.stack_height {
            return Err(());
        }
        let previous = self.clone();
        self.stack_values
            .retain(|slot, value| other.stack_values.get(slot) == Some(value));
        self.locals
            .retain(|slot, value| other.locals.get(slot) == Some(value));
        Ok(*self != previous)
    }

    fn apply_effect(
        &mut self,
        instruction: &Instruction,
        imports: &[crate::runtime::NativeImport],
    ) -> Result<(), ()> {
        let (pops, pushes) = instruction.stack_effect(imports).map_err(|_| ())?;
        let new_height = self.stack_height.checked_sub(pops).ok_or(())?;
        self.stack_values.retain(|slot, _| *slot < new_height);
        self.stack_height = new_height;
        for _ in 0..pushes {
            self.push(None)?;
        }
        Ok(())
    }
}

#[derive(Clone, Copy)]
struct BasicBlock {
    start: usize,
    end: usize,
}

struct RegionFacts {
    reachable: Vec<bool>,
    load_constants: HashMap<usize, Scalar>,
    redundant_stores: BTreeSet<usize>,
    branch_taken: HashMap<usize, bool>,
}

impl RegionFacts {
    fn conservative(length: usize) -> Self {
        Self {
            reachable: vec![true; length],
            load_constants: HashMap::new(),
            redundant_stores: BTreeSet::new(),
            branch_taken: HashMap::new(),
        }
    }
}

/// Optimizes compiler output. If a region exceeds the analysis budget or has
/// an unexpected shape, that region is preserved verbatim.
pub(crate) fn optimize(program: &CompiledProgram) -> CompiledProgram {
    let instruction_count = program.instructions.len();
    if instruction_count == 0 || instruction_count > crate::bytecode::LIMIT {
        return program.clone();
    }

    let mut boundaries = vec![0, instruction_count];
    for entry in program.callables.keys().copied() {
        if entry == 0 || entry >= instruction_count {
            return program.clone();
        }
        boundaries.push(entry);
    }
    boundaries.sort_unstable();
    boundaries.dedup();

    let mut rewritten = Vec::with_capacity(instruction_count);
    let mut old_to_new = vec![None; instruction_count + 1];
    let mut source_map = Vec::new();
    let mut source_index = 0;

    for window in boundaries.windows(2) {
        let start = window[0];
        let end = window[1];
        if start == end {
            continue;
        }
        let facts = analyze_region(program, start, end)
            .unwrap_or_else(|| RegionFacts::conservative(end - start));

        for pc in start..end {
            if !facts.reachable[pc - start] {
                continue;
            }
            old_to_new[pc] = Some(rewritten.len());
            let location = source_location(program, pc, &mut source_index);
            match &program.instructions[pc] {
                Instruction::Load(slot) if facts.load_constants.contains_key(&pc) => {
                    push_instruction(
                        &mut rewritten,
                        &mut source_map,
                        Instruction::Push(facts.load_constants[&pc].value()),
                        location,
                    );
                }
                Instruction::Store(_) if facts.redundant_stores.contains(&pc) => {
                    push_instruction(&mut rewritten, &mut source_map, Instruction::Pop, location);
                }
                Instruction::JumpIfFalse(target) | Instruction::JumpIfTrue(target)
                    if let Some(taken) = facts.branch_taken.get(&pc).copied() =>
                {
                    push_instruction(
                        &mut rewritten,
                        &mut source_map,
                        Instruction::Pop,
                        location.clone(),
                    );
                    if taken && *target != pc + 1 {
                        push_instruction(
                            &mut rewritten,
                            &mut source_map,
                            Instruction::Jump(*target),
                            location,
                        );
                    }
                }
                _ => push_instruction(
                    &mut rewritten,
                    &mut source_map,
                    program.instructions[pc].clone(),
                    location,
                ),
            }
            if rewritten.len() > crate::bytecode::LIMIT {
                return program.clone();
            }
        }
        old_to_new[end] = Some(rewritten.len());
    }
    old_to_new[instruction_count] = Some(rewritten.len());

    if rewritten.is_empty() {
        return program.clone();
    }
    for instruction in &mut rewritten {
        if !remap_instruction(instruction, &old_to_new) {
            return program.clone();
        }
    }

    let mut functions = BTreeMap::new();
    for (entry, name) in &program.functions {
        let Some(entry) = old_to_new.get(*entry).and_then(|entry| *entry) else {
            return program.clone();
        };
        functions.insert(entry, name.clone());
    }
    let Some(callables) = remap_callables(&program.callables, &old_to_new) else {
        return program.clone();
    };

    let mut optimized = CompiledProgram {
        instructions: rewritten,
        imports: program.imports.clone(),
        functions,
        callables,
        source_map,
    };
    compact_local_slots(&mut optimized);
    optimized
}

/// Reuses a local slot only when CFG liveness proves that its previous value is
/// dead. The analysis is bounded; oversized or unusual regions are untouched.
fn compact_local_slots(program: &mut CompiledProgram) {
    let instruction_count = program.instructions.len();
    let mut boundaries = vec![0, instruction_count];
    boundaries.extend(program.callables.keys().copied());
    boundaries.sort_unstable();
    boundaries.dedup();

    for window in boundaries.windows(2) {
        let (start, end) = (window[0], window[1]);
        if start >= end || end > instruction_count {
            continue;
        }
        let Some(mapping) = local_slot_mapping(program, start, end) else {
            continue;
        };
        for instruction in &mut program.instructions[start..end] {
            let slot = match instruction {
                Instruction::Load(slot) | Instruction::Store(slot) => slot,
                _ => continue,
            };
            if let Some(compact) = mapping.get(*slot) {
                *slot = *compact;
            }
        }
    }
}

fn local_slot_mapping(program: &CompiledProgram, start: usize, end: usize) -> Option<Vec<usize>> {
    let length = end.checked_sub(start)?;
    if length == 0 || length > MAX_REGION_INSTRUCTIONS {
        return None;
    }

    let mut slot_count = 0usize;
    for instruction in &program.instructions[start..end] {
        if let Instruction::Load(slot) | Instruction::Store(slot) = instruction {
            slot_count = slot_count.max(slot.checked_add(1)?);
        }
    }
    if slot_count == 0 || slot_count > MAX_SLOT_COMPACTION_SLOTS {
        return None;
    }

    let mut leaders = BTreeSet::from([start]);
    for pc in start..end {
        let instruction = &program.instructions[pc];
        if let Some(target) = branch_target(instruction) {
            if !(start..end).contains(&target) {
                return None;
            }
            leaders.insert(target);
        }
        if is_block_terminator(instruction) && pc + 1 < end {
            leaders.insert(pc + 1);
        }
    }

    let words = slot_count.checked_add(63)?.checked_div(64)?;
    let leaders = leaders.into_iter().collect::<Vec<_>>();
    let mut blocks = Vec::with_capacity(leaders.len());
    let mut pc_to_block = vec![usize::MAX; length];
    for (index, leader) in leaders.iter().copied().enumerate() {
        let block_end = leaders.get(index + 1).copied().unwrap_or(end);
        if leader >= block_end {
            return None;
        }
        blocks.push(BasicBlock {
            start: leader,
            end: block_end,
        });
        for pc in leader..block_end {
            pc_to_block[pc - start] = index;
        }
    }

    let flow_len = blocks.len().checked_mul(words)?;
    if flow_len > MAX_SLOT_FLOW_WORDS {
        return None;
    }
    let block_count = blocks.len();
    let mut uses = vec![0u64; flow_len];
    let mut definitions = vec![0u64; flow_len];
    let mut successors = Vec::with_capacity(block_count);
    let mut predecessors = vec![Vec::new(); block_count];
    for (block_index, block) in blocks.iter().enumerate() {
        let row = block_index * words;
        for pc in block.start..block.end {
            match &program.instructions[pc] {
                Instruction::Load(slot) => {
                    if !bit_is_set(&definitions[row..row + words], *slot) {
                        bit_set(&mut uses[row..row + words], *slot);
                    }
                }
                Instruction::Store(slot) => bit_set(&mut definitions[row..row + words], *slot),
                _ => {}
            }
        }
        let next = block_successors(
            &program.instructions[block.end - 1],
            block.end - 1,
            block_index,
            block_count,
            start,
            end,
            &pc_to_block,
            None,
        )?;
        for successor in next.into_iter().flatten() {
            if successor >= block_count {
                return None;
            }
            predecessors[successor].push(block_index);
        }
        successors.push(next);
    }

    let mut live_in = vec![0u64; flow_len];
    let mut live_out = vec![0u64; flow_len];
    let mut queue = (0..block_count).rev().collect::<VecDeque<_>>();
    let mut queued = vec![true; block_count];
    let mut next_out = vec![0u64; words];
    let mut flow_operations = 0usize;
    while let Some(block) = queue.pop_front() {
        queued[block] = false;
        next_out.fill(0);
        for successor in successors[block].into_iter().flatten() {
            let successor_row = successor * words;
            for (out, input) in next_out
                .iter_mut()
                .zip(&live_in[successor_row..successor_row + words])
            {
                *out |= *input;
            }
            flow_operations = flow_operations.checked_add(words)?;
        }

        let row = block * words;
        let mut changed = false;
        for word in 0..words {
            let incoming = uses[row + word] | (next_out[word] & !definitions[row + word]);
            if live_out[row + word] != next_out[word] || live_in[row + word] != incoming {
                live_out[row + word] = next_out[word];
                live_in[row + word] = incoming;
                changed = true;
            }
        }
        flow_operations = flow_operations.checked_add(words)?;
        if flow_operations > MAX_SLOT_FLOW_OPERATIONS {
            return None;
        }
        if changed {
            for predecessor in &predecessors[block] {
                if !queued[*predecessor] {
                    queued[*predecessor] = true;
                    queue.push_back(*predecessor);
                }
            }
        }
    }

    let interference_words = slot_count.checked_mul(words)?;
    if interference_words > MAX_SLOT_INTERFERENCE_OPERATIONS {
        return None;
    }
    let mut interference = vec![0u64; interference_words];
    let mut live = vec![0u64; words];
    let mut interference_operations = 0usize;
    for (block_index, block) in blocks.iter().enumerate() {
        let row = block_index * words;
        live.copy_from_slice(&live_out[row..row + words]);
        for pc in (block.start..block.end).rev() {
            match &program.instructions[pc] {
                Instruction::Store(slot) => {
                    for (word_index, word) in live.iter().copied().enumerate() {
                        let mut neighbors = word;
                        while neighbors != 0 {
                            let neighbor = word_index * 64 + neighbors.trailing_zeros() as usize;
                            neighbors &= neighbors - 1;
                            if neighbor >= slot_count || neighbor == *slot {
                                continue;
                            }
                            let slot_row = *slot * words;
                            let neighbor_row = neighbor * words;
                            bit_set(&mut interference[slot_row..slot_row + words], neighbor);
                            bit_set(&mut interference[neighbor_row..neighbor_row + words], *slot);
                            interference_operations = interference_operations.checked_add(1)?;
                            if interference_operations > MAX_SLOT_INTERFERENCE_OPERATIONS {
                                return None;
                            }
                        }
                    }
                    bit_clear(&mut live, *slot);
                }
                Instruction::Load(slot) => bit_set(&mut live, *slot),
                _ => {}
            }
        }
    }

    let mut degrees = Vec::with_capacity(slot_count);
    for slot in 0..slot_count {
        let row = slot * words;
        degrees.push(
            interference[row..row + words]
                .iter()
                .map(|word| word.count_ones() as usize)
                .sum::<usize>(),
        );
    }
    let mut order = (0..slot_count).collect::<Vec<_>>();
    order.sort_by(|left, right| {
        degrees[*right]
            .cmp(&degrees[*left])
            .then_with(|| left.cmp(right))
    });
    let mut colors = vec![usize::MAX; slot_count];
    let mut blocked = vec![false; slot_count];
    let mut color_count = 0usize;
    for slot in order {
        blocked.fill(false);
        let row = slot * words;
        for neighbor in 0..slot_count {
            if colors[neighbor] != usize::MAX
                && bit_is_set(&interference[row..row + words], neighbor)
            {
                blocked[colors[neighbor]] = true;
            }
        }
        let color = blocked.iter().position(|is_blocked| !is_blocked)?;
        colors[slot] = color;
        color_count = color_count.max(color + 1);
    }
    (color_count < slot_count).then_some(colors)
}

fn bit_is_set(bits: &[u64], index: usize) -> bool {
    bits.get(index / 64)
        .is_some_and(|word| word & (1u64 << (index % 64)) != 0)
}

fn bit_set(bits: &mut [u64], index: usize) {
    if let Some(word) = bits.get_mut(index / 64) {
        *word |= 1u64 << (index % 64);
    }
}

fn bit_clear(bits: &mut [u64], index: usize) {
    if let Some(word) = bits.get_mut(index / 64) {
        *word &= !(1u64 << (index % 64));
    }
}

fn analyze_region(program: &CompiledProgram, start: usize, end: usize) -> Option<RegionFacts> {
    let length = end.checked_sub(start)?;
    if length == 0 || length > MAX_REGION_INSTRUCTIONS {
        return None;
    }

    let mut leaders = BTreeSet::from([start]);
    for pc in start..end {
        let instruction = &program.instructions[pc];
        if let Some(target) = branch_target(instruction) {
            if !(start..end).contains(&target) {
                return None;
            }
            leaders.insert(target);
        }
        if is_block_terminator(instruction) && pc + 1 < end {
            leaders.insert(pc + 1);
        }
    }

    let leaders = leaders.into_iter().collect::<Vec<_>>();
    let mut blocks = Vec::with_capacity(leaders.len());
    let mut pc_to_block = vec![usize::MAX; length];
    for (index, leader) in leaders.iter().copied().enumerate() {
        let block_end = leaders.get(index + 1).copied().unwrap_or(end);
        if leader >= block_end {
            return None;
        }
        blocks.push(BasicBlock {
            start: leader,
            end: block_end,
        });
        for pc in leader..block_end {
            pc_to_block[pc - start] = index;
        }
    }

    let initial_stack = match program.callables.get(&start) {
        Some(signature) => signature.parameters,
        None => 0,
    };
    let mut incoming = vec![None; blocks.len()];
    incoming[0] = Some(State::new(initial_stack));
    let mut worklist = VecDeque::from([0]);
    let mut visits = 0usize;

    while let Some(block_index) = worklist.pop_front() {
        visits = visits.checked_add(blocks[block_index].end - blocks[block_index].start)?;
        if visits > MAX_ANALYSIS_VISITS {
            return None;
        }
        let block = blocks[block_index];
        let mut state = incoming[block_index].as_ref()?.clone();
        let mut branch_taken = None;
        for pc in block.start..block.end {
            branch_taken = execute(&mut state, &program.instructions[pc], &program.imports).ok()?;
        }

        let successors = block_successors(
            &program.instructions[block.end - 1],
            block.end - 1,
            block_index,
            blocks.len(),
            start,
            end,
            &pc_to_block,
            branch_taken,
        )?;
        for successor in successors.into_iter().flatten() {
            let slot = incoming.get_mut(successor)?;
            let changed = match slot {
                Some(existing) => existing.merge(&state).ok()?,
                None => {
                    *slot = Some(state.clone());
                    true
                }
            };
            if changed {
                worklist.push_back(successor);
            }
        }
    }

    let mut facts = RegionFacts {
        reachable: vec![false; length],
        load_constants: HashMap::new(),
        redundant_stores: BTreeSet::new(),
        branch_taken: HashMap::new(),
    };
    for (index, block) in blocks.iter().enumerate() {
        let Some(mut state) = incoming[index].clone() else {
            continue;
        };
        for pc in block.start..block.end {
            facts.reachable[pc - start] = true;
            match &program.instructions[pc] {
                Instruction::Load(slot) => {
                    if let Some(value) = state.locals.get(slot).copied() {
                        facts.load_constants.insert(pc, value);
                    }
                }
                Instruction::Store(slot) => {
                    if state.peek().is_some() && state.peek() == state.locals.get(slot).copied() {
                        facts.redundant_stores.insert(pc);
                    }
                }
                _ => {}
            }
            if let Some(taken) =
                execute(&mut state, &program.instructions[pc], &program.imports).ok()?
            {
                facts.branch_taken.insert(pc, taken);
            }
        }
    }
    Some(facts)
}

fn branch_target(instruction: &Instruction) -> Option<usize> {
    match instruction {
        Instruction::Jump(target)
        | Instruction::JumpIfFalse(target)
        | Instruction::JumpIfTrue(target)
        | Instruction::JumpIfNoPropagation(target) => Some(*target),
        _ => None,
    }
}

fn is_block_terminator(instruction: &Instruction) -> bool {
    matches!(
        instruction,
        Instruction::Jump(_)
            | Instruction::JumpIfFalse(_)
            | Instruction::JumpIfTrue(_)
            | Instruction::JumpIfNoPropagation(_)
            | Instruction::Return
            | Instruction::ReturnPropagate
            | Instruction::Crash(_)
            | Instruction::Halt
    )
}

fn block_successors(
    instruction: &Instruction,
    pc: usize,
    block_index: usize,
    block_count: usize,
    region_start: usize,
    region_end: usize,
    pc_to_block: &[usize],
    branch_taken: Option<bool>,
) -> Option<[Option<usize>; 2]> {
    let block_for_pc = |target: usize| {
        pc_to_block
            .get(target.checked_sub(region_start)?)
            .copied()
            .filter(|index| *index != usize::MAX)
    };
    let fallthrough = (pc + 1 < region_end)
        .then(|| block_for_pc(pc + 1))
        .flatten();
    Some(match instruction {
        Instruction::Jump(target) => [Some(block_for_pc(*target)?), None],
        Instruction::JumpIfFalse(target) | Instruction::JumpIfTrue(target) => match branch_taken {
            Some(true) => [Some(block_for_pc(*target)?), None],
            Some(false) => [fallthrough, None],
            None => [Some(block_for_pc(*target)?), fallthrough],
        },
        Instruction::JumpIfNoPropagation(target) => [Some(block_for_pc(*target)?), fallthrough],
        Instruction::Return
        | Instruction::ReturnPropagate
        | Instruction::Crash(_)
        | Instruction::Halt => [None, None],
        _ => [
            (block_index + 1 < block_count).then_some(block_index + 1),
            None,
        ],
    })
}

/// Returns the conditional branch's actual taken state when it is statically
/// known. Other instructions return `None`.
fn execute(
    state: &mut State,
    instruction: &Instruction,
    imports: &[crate::runtime::NativeImport],
) -> Result<Option<bool>, ()> {
    match instruction {
        Instruction::Push(value) => state.push(Scalar::from_value(value))?,
        Instruction::Load(slot) => state.push(state.locals.get(slot).copied())?,
        Instruction::Store(slot) => {
            let value = state.pop()?;
            state.store_local(*slot, value);
        }
        Instruction::Dup => {
            if state.stack_height == 0 {
                return Err(());
            }
            state.push(state.peek())?;
        }
        Instruction::Pop => {
            state.pop()?;
        }
        Instruction::Swap => {
            let right = state.pop()?;
            let left = state.pop()?;
            state.push(right)?;
            state.push(left)?;
        }
        Instruction::Not => {
            let value = state.pop()?;
            let folded = value.and_then(|value| {
                crate::comptime::fold_scalar_expression(&Expr::Unary(
                    UnOp::Not,
                    Box::new(value.expression()),
                ))
                .as_ref()
                .and_then(Scalar::from_value)
            });
            state.push(folded)?;
        }
        Instruction::IsType(ty) => {
            let value = state.pop()?;
            state.push(value.map(|value| Scalar::Bool(value.is_type(ty))))?;
        }
        Instruction::Add
        | Instruction::Sub
        | Instruction::Mul
        | Instruction::Div
        | Instruction::Mod
        | Instruction::Eq
        | Instruction::Ne
        | Instruction::Lt
        | Instruction::Le
        | Instruction::Gt
        | Instruction::Ge
        | Instruction::And
        | Instruction::Or
        | Instruction::Xor => {
            let right = state.pop()?;
            let left = state.pop()?;
            let folded = left
                .zip(right)
                .and_then(|(left, right)| fold_binary(instruction, left, right));
            state.push(folded)?;
        }
        Instruction::JumpIfFalse(_) | Instruction::JumpIfTrue(_) => {
            let condition = state.pop()?;
            return Ok(condition
                .and_then(|value| match value {
                    Scalar::Bool(value) => Some(value),
                    _ => None,
                })
                .map(|value| match instruction {
                    Instruction::JumpIfFalse(_) => !value,
                    Instruction::JumpIfTrue(_) => value,
                    _ => unreachable!(),
                }));
        }
        Instruction::StackTruncate(depth) => {
            if *depth > state.stack_height {
                return Err(());
            }
            state.stack_height = *depth;
            state.stack_values.retain(|slot, _| *slot < *depth);
        }
        Instruction::Jump(_) | Instruction::JumpIfNoPropagation(_) => {}
        _ => state.apply_effect(instruction, imports)?,
    }
    Ok(None)
}

fn fold_binary(instruction: &Instruction, left: Scalar, right: Scalar) -> Option<Scalar> {
    let op = match instruction {
        Instruction::Add => BinOp::Add,
        Instruction::Sub => BinOp::Sub,
        Instruction::Mul => BinOp::Mul,
        Instruction::Div => BinOp::Div,
        Instruction::Mod => BinOp::Mod,
        Instruction::Eq => BinOp::Eq,
        Instruction::Ne => BinOp::NotEq,
        Instruction::Lt => BinOp::Lt,
        Instruction::Le => BinOp::LtEq,
        Instruction::Gt => BinOp::Gt,
        Instruction::Ge => BinOp::GtEq,
        Instruction::And => BinOp::And,
        Instruction::Or => BinOp::Or,
        Instruction::Xor => BinOp::Xor,
        _ => return None,
    };
    let expression = Expr::Binary(
        op,
        Box::new(left.expression()),
        Box::new(right.expression()),
    );
    crate::comptime::fold_scalar_expression(&expression)
        .as_ref()
        .and_then(Scalar::from_value)
}

fn source_location(
    program: &CompiledProgram,
    pc: usize,
    source_index: &mut usize,
) -> Option<crate::diagnostic::SourceLocation> {
    while program
        .source_map
        .get(*source_index)
        .is_some_and(|entry| entry.end <= pc)
    {
        *source_index += 1;
    }
    program
        .source_map
        .get(*source_index)
        .filter(|entry| entry.start <= pc && pc < entry.end)
        .map(|entry| entry.location.clone())
}

fn push_instruction(
    instructions: &mut Vec<Instruction>,
    source_map: &mut Vec<SourceMapEntry>,
    instruction: Instruction,
    location: Option<crate::diagnostic::SourceLocation>,
) {
    let pc = instructions.len();
    instructions.push(instruction);
    let Some(location) = location else {
        return;
    };
    if let Some(previous) = source_map.last_mut()
        && previous.end == pc
        && previous.location == location
    {
        previous.end += 1;
    } else {
        source_map.push(SourceMapEntry {
            start: pc,
            end: pc + 1,
            location,
        });
    }
}

fn remap_instruction(instruction: &mut Instruction, old_to_new: &[Option<usize>]) -> bool {
    fn remap(target: &mut usize, old_to_new: &[Option<usize>]) -> bool {
        let Some(mapped) = old_to_new.get(*target).and_then(|target| *target) else {
            return false;
        };
        *target = mapped;
        true
    }

    match instruction {
        Instruction::Jump(target)
        | Instruction::JumpIfFalse(target)
        | Instruction::JumpIfTrue(target)
        | Instruction::JumpIfNoPropagation(target)
        | Instruction::Call(target, _)
        | Instruction::CallAsync(target, _)
        | Instruction::MakeClosure(target, _) => remap(target, old_to_new),
        Instruction::Push(Value::Function(target)) => remap(target, old_to_new),
        Instruction::PushArray(template) => remap_template(template, old_to_new),
        _ => true,
    }
}

fn remap_template(template: &mut ArrayTemplate, old_to_new: &[Option<usize>]) -> bool {
    match template {
        ArrayTemplate::Scalar(Value::Function(target)) => {
            let Some(mapped) = old_to_new.get(*target).and_then(|target| *target) else {
                return false;
            };
            *target = mapped;
            true
        }
        ArrayTemplate::Scalar(_) => true,
        ArrayTemplate::Array(items) => items
            .iter_mut()
            .all(|item| remap_template(&mut item.template, old_to_new)),
    }
}

fn remap_callables(
    callables: &BTreeMap<usize, CallableSignature>,
    old_to_new: &[Option<usize>],
) -> Option<BTreeMap<usize, CallableSignature>> {
    let mut remapped = BTreeMap::new();
    for (entry, signature) in callables {
        remapped.insert(*old_to_new.get(*entry)?.as_ref()?, signature.clone());
    }
    Some(remapped)
}
